import React from 'react';
import ProductCard from '../components/ProductCard';
import CategoryNav from '../components/CategoryBar';
import { ShoppingCart, TrendingUp, Truck, Shield } from 'lucide-react';

// Sample product data
const products = [
  {
    id: 1,
    name: 'iPhone 15 Pro Max - 256GB',
    brand: 'Apple',
    price: 149900,
    originalPrice: 159900,
    rating: 4.8,
    reviews: 2345,
    discount: 7,
    image: 'https://images.unsplash.com/photo-1695048133142-1a20484d2569?w=400&h=400&fit=crop'
  },
  {
    id: 2,
    name: 'Samsung Galaxy S24 Ultra',
    brand: 'Samsung',
    price: 129999,
    originalPrice: 139999,
    rating: 4.7,
    reviews: 1876,
    discount: 10,
    image: 'https://images.unsplash.com/photo-1610945415295-d9bbf067e59c?w=400&h=400&fit=crop'
  },
  {
    id: 3,
    name: 'MacBook Air M3 - 13-inch',
    brand: 'Apple',
    price: 114900,
    originalPrice: 124900,
    rating: 4.9,
    reviews: 3456,
    discount: 8,
    image: 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=400&h=400&fit=crop'
  },
  {
    id: 4,
    name: 'Sony WH-1000XM5 Headphones',
    brand: 'Sony',
    price: 29990,
    originalPrice: 34990,
    rating: 4.8,
    reviews: 678,
    discount: 15,
    image: 'https://images.unsplash.com/photo-1618366712010-f4ae9c647dcb?w=400&h=400&fit=crop'
  },
  {
    id: 5,
    name: 'Dell XPS 15 - Laptop',
    brand: 'Dell',
    price: 149990,
    originalPrice: 169990,
    rating: 4.6,
    reviews: 987,
    discount: 12,
    image: 'https://images.unsplash.com/photo-1593642632823-8f785ba67e45?w=400&h=400&fit=crop'
  },
  {
    id: 6,
    name: 'iPad Pro M2 - 11-inch',
    brand: 'Apple',
    price: 79900,
    originalPrice: 89900,
    rating: 4.8,
    reviews: 1234,
    discount: 11,
    image: 'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?w=400&h=400&fit=crop'
  }
];

const Home = () => {
  return (
    <div className="min-h-screen bg-gray-100">
      <CategoryNav />
      
      {/* Hero Banner */}
      <div className="max-w-7xl mx-auto px-4 py-4">
        <div className="bg-gradient-to-r from-blue-600 to-purple-600 rounded-xl p-8 text-white">
          <h2 className="text-3xl font-bold">🔥 Big Sale!</h2>
          <p className="text-lg opacity-90">Up to 70% off on electronics</p>
          <button className="mt-4 bg-white text-blue-600 px-6 py-2 rounded-lg font-bold hover:shadow-lg transition-shadow">
            Shop Now
          </button>
        </div>
      </div>

      {/* Quick Features */}
      <div className="max-w-7xl mx-auto px-4">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
          {[
            { icon: ShoppingCart, label: 'Free Delivery' },
            { icon: TrendingUp, label: 'Best Prices' },
            { icon: Truck, label: 'Fast Shipping' },
            { icon: Shield, label: 'Secure Payment' }
          ].map((feature, index) => {
            const Icon = feature.icon;
            return (
              <div key={index} className="bg-white p-4 rounded-lg shadow-sm flex items-center space-x-3">
                <Icon className="text-blue-600" size={24} />
                <span className="text-sm font-medium">{feature.label}</span>
              </div>
            );
          })}
        </div>
      </div>

      {/* Products Grid */}
      <div className="max-w-7xl mx-auto px-4 pb-8">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-2xl font-bold text-gray-800">Featured Products</h2>
          <button className="text-blue-600 hover:text-blue-800 font-semibold">
            View All →
          </button>
        </div>
        
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
          {products.map(product => (
            <ProductCard key={product.id} product={product} />
          ))}
        </div>
      </div>
    </div>
  );
};

export default Home;
